        <PanelContent className="flex flex-wrap gap-2">
          {site.socials.map((social) => {
            const Glyph = SOCIAL_ICONS[social.label];
            const isMail = social.href.startsWith("mailto:");
            return (
              <a
                key={social.label}
                href={social.href}
                target={isMail ? undefined : "_blank"}
                rel="noopener noreferrer"
