          />
          <span
            aria-hidden
            className="relative font-heading text-5xl font-medium tracking-tight text-foreground sm:text-6xl"
          >
            {initials(site.name)}
          </span>
        </span>
      )}
    </div>
  );
}

/**
 * The figure has no axis, so the tiles are not decoration on it — they are the
 * only place the ridge's quantities are written down, and they are what makes a
 * silhouette with no scale an honest thing to draw. Four nested windows on one
 * number: a lifetime total goes up and never comes down, so on its own it says
 * nothing about whether the habit is still alive.
 */
function Stat({ label, tokens }: { label: string; tokens: number }) {
  return (
    <div className="bg-background px-3 py-2.5">
      <dt className="font-mono text-[0.6875rem]/none text-muted-foreground">
        {label}
      </dt>
      <dd
        className="mt-1 font-mono text-lg/none font-medium tabular-nums"
        title={`${formatTokenCount(tokens)} tokens`}
      >
        {formatCompactTokens(tokens)}
      </dd>
    </div>
  );
}

/**
 * The hero is a four-cell frame rather than a stacked block: the figure runs
 * the full width of the rail behind everything, the tiles and the monogram
 * stack against the bottom of their own gutter column, and the name and role
 * stack against the bottom edge so all three meet on one baseline. Everything
 * that is not the drawing is opaque and is cut out of it. Nothing here is
 * centred.
 */
export async function ProfileHeader() {
  const { payload } = await getAiActivityPayload();
  const { days, totals } = materializeAiActivity(payload);

  return (
    <div className="screen-line-bottom relative grid grid-cols-[auto_1fr] grid-rows-[1fr_auto] overflow-clip border-x border-line">
      {/* Nothing bleeds out of here. The reference lets its hero texture run
          past the rail and off the screen; ours does not. The drawing is cut
          by the frame, by the gutter column and by the name block, and it is
          those cuts that keep it attached to the page instead of floating on
          it. */}
      <figure className="relative col-span-2 col-start-1 row-start-1 flex aspect-2/1 min-h-64 items-end justify-end p-2 sm:p-4">
        <TokenRidge days={days} className="absolute inset-0 size-full" />
        <figcaption className="pointer-events-none relative text-sm leading-none tracking-wide text-[color-mix(in_oklab,var(--muted-foreground)_60%,var(--background))] tabular-nums select-none">
          Fig. 1.
          {/* Said out loud, because a silhouette says none of it. The exact
              daily numbers are Fig. 2's job; this one is a shape. */}
          <span className="sr-only">
            {" "}
            Daily token use from {days[0]?.date} to{" "}
            {days[days.length - 1]?.date}, smoothed over {RIDGE_SMOOTHING} days.
            Exact daily figures are in the token activity grid below.
          </span>
        </figcaption>
      </figure>

      <div className="relative z-1 flex flex-col sm:row-span-2 sm:row-start-1">
        {/* Hairlines by gap rather than by border, so the rules between tiles
            are drawn by the one colour the frame uses everywhere else. */}
        <dl className="screen-line-top mt-auto grid gap-px border-r border-line bg-line">
          <Stat label="all time" tokens={totals.lifetime} />
          <Stat label="30 days" tokens={totals.days30} />
          <Stat label="7 days" tokens={totals.days7} />
          <Stat label="today" tokens={totals.today} />
        </dl>
        <div className="shrink-0 border-t border-r border-line bg-background">
          <Avatar />
        </div>
      </div>

      <div className="relative z-1 flex flex-col">
        <div className="mt-auto border-t border-line bg-background">
          <h1 className="-translate-y-px flex items-center gap-2 pl-4 text-[2rem]/none font-medium tracking-tight">
            {site.name}
            {/* Inside the heading, not beside it: the button is about this
                name, and a name and the way to hear it are one object. */}
            <PronounceName />
          </h1>
          {/* The one line that reads as a caption rather than as prose, so it
              is set in mono at the small size — and swept once on arrival,
              which is the reference's own way of pointing at it without
              shouting. */}
          <FlipSentences
            sentences={site.flipSentences}
            className="h-12.5 border-t border-line py-1 pl-4 font-mono text-sm text-balance text-muted-foreground sm:h-9"
          />
        </div>
      </div>
    </div>
  );
}
