import { describe, expect, test } from "bun:test";
import fallback from "@/data/ai-activity.fallback.json";
import { buildDailySeries } from "@/lib/ai-activity";
import {
  buildTokenRidge,
  RIDGE_SMOOTHING,
  smoothSeries,
} from "@/lib/token-ridge";

const sum = (xs: readonly number[]) => xs.reduce((a, b) => a + b, 0);

describe("smoothSeries", () => {
  test("loses no mass off either end", () => {
    const raw = Array.from({ length: 200 }, (_, i) => (i === 3 ? 1000 : i % 7));
    const smoothed = smoothSeries(raw);
    expect(smoothed).toHaveLength(raw.length);
    expect(sum(smoothed)).toBeCloseTo(sum(raw), 6);
  });

  test("flattens the spike that would otherwise own the scale", () => {
    const raw = Array.from({ length: 100 }, (_, i) => (i === 50 ? 600 : 10));
    expect(Math.max(...smoothSeries(raw))).toBeLessThan(Math.max(...raw) / 4);
  });

  test("a series shorter than the window is passed through", () => {
    const raw = [1, 2, 3];
    expect(smoothSeries(raw, RIDGE_SMOOTHING)).toEqual(raw);
  });
});

describe("buildTokenRidge", () => {
  test("draws nothing when there is nothing to draw", () => {
    const days = Array.from({ length: 40 }, (_, i) => ({
      date: `2026-01-${String(i + 1).padStart(2, "0")}`,
      tokens: 0,
    }));
    expect(buildTokenRidge(days).line).toBe("");
  });

  test("spans the full width and closes to the floor", () => {
    const days = buildDailySeries(fallback.days, "2025-08-24", "2026-08-20");
    const ridge = buildTokenRidge(days);
    expect(ridge.line.startsWith("M0,")).toBe(true);
    expect(ridge.area.endsWith("L1000,100L0,100Z")).toBe(true);
    expect(ridge.span.days).toBe(days.length);
  });

  test("keeps the peak inside the plate", () => {
    const days = buildDailySeries(fallback.days, "2025-08-24", "2026-08-20");
    const ys = buildTokenRidge(days)
      .line.slice(1)
      .split("L")
      .map((p) => Number(p.split(",")[1]));
    expect(Math.min(...ys)).toBeGreaterThan(0);
    expect(Math.max(...ys)).toBeLessThanOrEqual(100);
  });
});
